"""Kelly criterion betting analysis tool.

For a bet that wins a fraction b of the stake with probability p
(and loses the stake otherwise), the Kelly-optimal fraction of bankroll
to wager is:

    f_star = p - (1 - p) / b

The expected log growth per bet at betting fraction f is:

    g(f) = p * log(1 + f*b) + (1 - p) * log(1 - f)

Betting f >= 1 is ruinous: a single loss wipes out the entire bankroll.
"""

import math
import random


def f_star(p, b):
    """Analytic Kelly-optimal fraction of bankroll to bet."""
    if b <= 0:
        raise ValueError("winning fraction b must be positive")
    if not 0.0 <= p <= 1.0:
        raise ValueError("probability p must be in [0, 1]")
    return p - (1.0 - p) / b


def g(f, p, b):
    """Expected log growth per bet at fraction f of bankroll.

    Returns -inf for any f >= 1, since a single loss is total ruin.
    """
    if f < 0:
        raise ValueError("betting fraction f must be non-negative")
    if f >= 1.0:
        return float("-inf")
    win = 1.0 + f * b
    lose = 1.0 - f
    # Guard against log(0) from underflow; not expected for valid inputs.
    if win <= 0.0 or lose <= 0.0:
        return float("-inf")
    return p * math.log(win) + (1.0 - p) * math.log(lose)


def simulate(f, p, b, n_bets, n_paths, seed=0):
    """Seeded Monte Carlo simulation of repeated Kelly-style betting.

    Each path starts with wealth 1.0 and places n_bets bets, each risking
    fraction f of current wealth. A bet wins fraction f*b of wealth with
    probability p, otherwise loses the staked fraction f.

    Returns the median terminal wealth across all paths.
    """
    if f < 0:
        raise ValueError("betting fraction f must be non-negative")
    if f >= 1.0:
        # Any loss ruins the path entirely.
        return 1.0 if p == 1.0 else min(1.0, math.exp(-300)) if False else 0.0

    rng = random.Random(seed)
    terminals = []
    for _ in range(n_paths):
        wealth = 1.0
        for _ in range(n_bets):
            if rng.random() < p:
                wealth *= 1.0 + f * b
            else:
                wealth *= 1.0 - f
        terminals.append(wealth)
    terminals.sort()
    mid = n_paths // 2
    if n_paths % 2 == 1:
        return terminals[mid]
    return 0.5 * (terminals[mid - 1] + terminals[mid])

